const brochurePng = '';

    (() => {
      const frame = document.querySelector('.frame');
      const sheet = document.querySelector('.brochure');
      let printing = false;
      const printMedia = window.matchMedia('print');
      const fit = () => {
        if (printing || printMedia.matches) { sheet.style.transform = 'none'; return; }
        sheet.style.transform = 'scale(' + (frame.clientWidth / sheet.offsetWidth) + ')';
      };
      window.addEventListener('beforeprint', () => { printing = true; sheet.style.transform = 'none'; });
      window.addEventListener('afterprint', () => { printing = false; requestAnimationFrame(fit); });
      window.printBrochure = async () => {
        if (document.fonts) await document.fonts.ready;
        await Promise.all(Array.from(document.images).map(img => img.decode ? img.decode().catch(() => {}) : Promise.resolve()));
        window.print();
      };
      window.downloadBrochurePng = () => {
        const encoded = brochurePng.trim();
        if (!encoded) return;
        const bytes = Uint8Array.from(atob(encoded), character => character.charCodeAt(0));
        const url = URL.createObjectURL(new Blob([bytes], { type:'image/png' }));
        const link = document.createElement('a');
        link.href = url;
        link.download = 'Riyaziyyat-Olimpiada-Dersleri-2026-2027.png';
        link.hidden = true;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 30000);
      };
      fit();
      if ('ResizeObserver' in window) new ResizeObserver(fit).observe(frame);
      else window.addEventListener('resize', fit);
    })();
  